 static int assertions,failures; static string currentCase;
 static Dictionary<string,string> HashInputs(){var folder=Path.GetDirectoryName(xaml);var tests=Path.Combine(Directory.GetParent(folder).FullName,"tests");var files=Directory.GetFiles(folder,"*.cs").Where(p=>Path.GetFileName(p).StartsWith("Monitor",StringComparison.Ordinal)||Path.GetFileName(p)=="ApiBridge.cs"||Path.GetFileName(p)=="ApiMonitor.cs").Concat(new[]{xaml,Path.Combine(folder,"CachePilot.Monitor.exe"),System.Reflection.Assembly.GetExecutingAssembly().Location}).Concat(Directory.GetFiles(tests,"ui-*.cs")).Concat(Directory.GetFiles(tests,"ui-*.ps1")).OrderBy(p=>p,StringComparer.Ordinal).ToArray();var result=new Dictionary<string,string>();foreach(string file in files)using(var sha=SHA256.Create())result[Path.GetFileName(file)]=BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(file))).Replace("-","").ToLowerInvariant();return result;}
 static void AddTrace(object value){lock(Trace)Trace.Add(value);}
 static void Check(bool condition,string message){assertions++;if(!condition)throw new Exception(currentCase+": "+message);}
 static bool Eq(double? value,double expected){return value.HasValue&&Math.Abs(value.Value-expected)<0.000001;}
 static string Text(Window window,string name){return ((TextBlock)window.FindName(name)).Text;}
 static Dictionary<string,object> Raw(int pid,long tokens,long inputs,long? hits,long started=100000,string backend="estimate"){
  long h=hits??0;
  return new Dictionary<string,object>{{"schema",2},{"pid",pid},{"startedAt",started},{"sampledAt",1700000000000L},{"version","0.6.8"},{"device","off"},{"backend",backend},{"hits",h},{"misses",Math.Max(0,inputs-h)},{"reusedWithinCall",0},{"tokenizations",inputs},{"preparations",0},{"promptPreparations",0},{"failures",0},{"active",0},{"queued",0},{"rss",4096},{"providerCacheMeasured",false},{"hostRequestsIntercepted",false},{"analyses",inputs},{"inputPositions",inputs},{"cacheHitPositions",hits.HasValue?(object)hits.Value:null},{"cacheMissPositions",Math.Max(0,inputs-h)},{"lastInputTokens",0},{"totalInputTokens",tokens},{"lastCompletedAt",1700000000000L}};
 }
 sealed class Fixture:IDisposable {
  public long Now=1000; public readonly Dictionary<int,long> Identity=new Dictionary<int,long>{{A,11001},{B,11002},{C,11003}};
  public readonly MonitorReceiver Receiver;public readonly MonitorHistory History=new MonitorHistory();public readonly Window Window;
  public ReceiverView View;public int Renders;
  public Fixture(long initialSequence=0){Receiver=new MonitorReceiver(()=>Now,()=>1700000000000L+Now,p=>Identity.ContainsKey(p),p=>Identity.ContainsKey(p)?(long?)Identity[p]:null,initialSequence);Window=(Window)XamlReader.Parse(File.ReadAllText(xaml,Encoding.UTF8));((FrameworkElement)Window.FindName("DetailsScroller")).Visibility=Visibility.Collapsed;var content=(FrameworkElement)Window.Content;content.Measure(new Size(420,Double.PositiveInfinity));content.Arrange(new Rect(0,0,420,content.DesiredSize.Height));content.UpdateLayout();}
  public void Select(int pid,string phase){Receiver.Select(pid);Refresh(phase);}
  void TicketTrace(string operation,ReceiverTicket ticket,int? ordinal,bool? accepted,string phase,ReceiverBoundary before,ReceiverBoundary after){AddTrace(new{test=currentCase,operation,phase,now=Now,accepted,actualPid=ticket.ActualPid,originSeq=ticket.OriginSeq,frameOrdinal=ordinal,transportConnectionId=ticket.TransportConnectionId,epoch=ticket.Epoch,ticket.SourceSessionGeneration,ticket.ProcessIdentity,ticket.ReservedMonotonicMilliseconds,watermark=before.Watermark,generation=before.SelectionGeneration,selectedPid=before.SelectedPid,afterWatermark=after.Watermark,afterGeneration=after.SelectionGeneration,afterBoundaryReason=after.Reason,rejectionPhase=accepted==false?phase:null,reasonSource="harness operation phase; no fabricated internal rejection-code claim"});}
  public ReceiverTicket Reserve(int pid){var before=Receiver.Capture().Boundary;var ticket=Receiver.Reserve(pid);TicketTrace("reserve-before-read",ticket,null,null,"receiver-issued origin reservation",before,Receiver.Capture().Boundary);return ticket;}
  public ReceiverTicket ReserveRead(ReceiverTicket first){var before=Receiver.Capture().Boundary;var ticket=Receiver.ReserveRead(first);TicketTrace("reserve-continuation-read",ticket,null,null,"continuation preserves earliest frame origin",before,Receiver.Capture().Boundary);return ticket;}
  public bool CommitAttempt(ReceiverTicket ticket,Dictionary<string,object> parsed,int ordinal,string phase="direct production receiver commit"){var before=Receiver.Capture().Boundary;bool accepted=Receiver.Commit(ticket,parsed,ordinal);TicketTrace("commit-attempt",ticket,ordinal,accepted,phase,before,Receiver.Capture().Boundary);return accepted;}
  public void Reject(ReceiverTicket ticket,string reason){var before=Receiver.Capture().Boundary;Receiver.Reject(ticket,reason);TicketTrace("reject-transport",ticket,null,false,reason,before,Receiver.Capture().Boundary);}
  public bool Commit(ReceiverTicket ticket,long tokens,long n,long? h,string phase,int ordinal=0,long started=100000,string backend="estimate",bool normalEnd=true){
   var parsed=FrameCodec.Parse(Json.Serialize(Raw(ticket.ActualPid,tokens,n,h,started,backend)),(uint)ticket.ActualPid,1700000000000L+Now);
   bool accepted=CommitAttempt(ticket,parsed,ordinal,phase);if(normalEnd)Receiver.EndTransport(ticket,true);Refresh(phase);return accepted;
  }
  public bool Send(int pid,long tokens,long n,long? h,string phase,long advance=100){Now+=advance;var ticket=Reserve(pid);Receiver.MarkBytes(ticket);return Commit(ticket,tokens,n,h,phase);}
  public void Refresh(string phase){View=Receiver.Capture();bool rendered=MonitorApp.ApplyView(Window,History,Receiver,View,p=>Identity.ContainsKey(p));if(rendered)Renders++;Record(phase,rendered);}
  void Record(string phase,bool rendered){
   var boundary=View.Boundary;var last=History.LatestWindow;
   foreach(var frame in View.AcceptedSamples){Check(frame.Stamp.OriginSeq>boundary.Watermark,"every adopted frame exceeds fixed segment watermark");Check(frame.Stamp.Epoch==boundary.Epoch,"every adopted frame belongs to current bridge epoch");Check(frame.Stamp.SelectionGeneration==boundary.SelectionGeneration,"every adopted frame has current selection generation");Check(frame.Stamp.ActualPid==boundary.SelectedPid,"every adopted frame comes from pinned PID");}
   var byId=View.AcceptedSamples.ToDictionary(s=>s.Stamp.FrameId);foreach(var point in History.Points){Check(byId.ContainsKey(point.FrameId)&&byId.ContainsKey(point.BaselineFrameId),"each plotted endpoint refers to an adopted real receipt identity");var end=byId[point.FrameId];var start=byId[point.BaselineFrameId];Check(start.Stamp.ActualPid==end.Stamp.ActualPid&&end.Stamp.ActualPid==boundary.SelectedPid&&start.Stamp.ProcessIdentity==end.Stamp.ProcessIdentity&&start.Stamp.StartedAt==end.Stamp.StartedAt&&start.Stamp.Backend==end.Stamp.Backend&&start.Stamp.SourceSessionGeneration==end.Stamp.SourceSessionGeneration,"plotted numerator denominator and baseline share pinned lifetime backend session");Check(point.Watermark==boundary.Watermark&&point.SelectionGeneration==boundary.SelectionGeneration&&start.Stamp.OriginSeq>point.Watermark&&end.Stamp.OriginSeq>point.Watermark,"both plotted endpoints are strictly beyond same fixed segment watermark");long delta=Convert.ToInt64(end.Data["totalInputTokens"])-Convert.ToInt64(start.Data["totalInputTokens"]);Check(!point.WindowTokens.HasValue||point.WindowTokens.Value==delta,"plotted token is direct endpoint subtraction, never carried old amount");}
   AddTrace(new{test=currentCase,operation="paint",phase,now=Now,rendered,selectedPid=boundary.SelectedPid,watermark=boundary.Watermark,generation=boundary.SelectionGeneration,epoch=boundary.Epoch,boundaryAt=boundary.AtMilliseconds,boundaryReason=boundary.Reason,View.Live,receiverState=View.State,actualPid=View.Current==null?(int?)null:View.Current.Stamp.ActualPid,receipt=View.Current==null?null:(object)View.Current.Stamp,accepted=View.AcceptedSamples.Select(s=>s.Stamp).ToArray(),baselineId=History.BaselineFrameId,baselineOriginSeq=History.BaselineOriginSeq,baselineReceivedAt=History.BaselineReceivedAt,baselineMonotonic=History.BaselineMonotonicMilliseconds,hasBaseline=History.HasBaseline,historyState=History.CurrentState,postBaselineFrames=History.PostBaselineFrameCount,calculatedTokens=History.CalculatedWindowTokens,inputs=History.WindowInputPositions,hits=History.WindowHitPositions,calculatedRate=History.CalculatedWindowHitRatePercent,observedMs=History.ObservedMilliseconds,windowTokenText=Text(Window,"WindowTokenValue"),windowRateText=Text(Window,"WindowRateValue"),chartState=Text(Window,"ChartState"),tokenPoints=History.Points.Count(p=>p.WindowTokens.HasValue),ratePoints=History.Points.Count(p=>p.WindowHitRatePercent.HasValue),tokenVisuals=((Canvas)Window.FindName("TokenChart")).Children.Count,rateVisuals=((Canvas)Window.FindName("RateChart")).Children.Count,visibleTokens=last==null?(double?)null:last.WindowTokens,visibleRate=last==null?(double?)null:last.WindowHitRatePercent});
  }
  public void AtomicRecord(ReceiverView painted,string phase){View=painted;Record(phase,true);}
  public void Empty(string phase){Check(!History.HasBaseline,phase+" has no old baseline");Check(History.LatestWindow==null||(!History.LatestWindow.WindowTokens.HasValue&&!History.LatestWindow.WindowHitRatePercent.HasValue),phase+" no fabricated measured values");Check(((Canvas)Window.FindName("TokenChart")).Children.Count==0&&((Canvas)Window.FindName("RateChart")).Children.Count==0,phase+" old curves cleared");Check(!Text(Window,"WindowRateValue").Contains("%"),phase+" percentage hidden");}
  public void Baseline(long tokens,long n,long h,string phase){Check(History.HasBaseline,phase+" baseline exists");Check(History.LatestWindow==null,phase+" baseline has no measured interval");Check(History.PostBaselineFrameCount==0,phase+" baseline does not count as post-baseline sample");Check(History.ObservedMilliseconds==0,phase+" coverage zero");Check(Text(Window,"WindowTokenValue")=="基线建立中"&&Text(Window,"WindowRateValue")=="基线建立中",phase+" actual UI baseline labels");Check(Convert.ToInt64(View.Current.Data["totalInputTokens"])==tokens&&Convert.ToInt64(View.Current.Data["inputPositions"])==n&&Convert.ToInt64(View.Current.Data["cacheHitPositions"])==h,phase+" raw new baseline preserved");Check(((Canvas)Window.FindName("TokenChart")).Children.Count==0&&((Canvas)Window.FindName("RateChart")).Children.Count==0,phase+" zero plotted baseline points");}
  public void Insufficient(string phase){Check(Text(Window,"WindowRateValue")=="样本不足",phase+" insufficient label");Check(!Text(Window,"WindowRateValue").Contains("%"),phase+" percentage hidden");Check(((Canvas)Window.FindName("RateChart")).Children.Count==0,phase+" no hit-rate plot or fake zero");Check(((FrameworkElement)Window.FindName("RateAxis")).Visibility==Visibility.Hidden&&((Canvas)Window.FindName("RateChart")).Visibility==Visibility.Hidden,phase+" empty rate chart and percentage axes are both hidden");}
  public void Values(double tokens,long n,long h,double rate,string phase){Check(Eq(History.CalculatedWindowTokens,tokens),phase+" exact token difference");Check(History.WindowInputPositions==n&&History.WindowHitPositions==h,phase+" same-window denominator and numerator");Check(Eq(History.CalculatedWindowHitRatePercent,rate),phase+" exact measured formula");Check(Text(Window,"WindowTokenValue")==tokens.ToString("N0",CultureInfo.InvariantCulture),phase+" actual token text");Check(Text(Window,"WindowRateValue")==rate.ToString("F1",CultureInfo.InvariantCulture)+"%",phase+" actual percentage text");}
  public void Dispose(){Window.Close();}
 }
 static void Run(string id,string name,Action test){currentCase=id;int before=assertions;int start=Trace.Count;try{test();Cases.Add(new{id,name,passed=true,assertions=assertions-before,traceStart=start,traceCount=Trace.Count-start});Console.WriteLine(id+" PASS "+(assertions-before));}catch(Exception error){failures++;Cases.Add(new{id,name,passed=false,assertions=assertions-before,traceStart=start,traceCount=Trace.Count-start,error=error.Message});Console.WriteLine(id+" FAIL "+error.Message);}}
 static Fixture ReadyB(){var f=new Fixture();f.Select(B,"pin B creates receive barrier");return f;}
