  f.Send(B,470,10,7,"B old cached frame while A selected");var cached=f.Receiver.Capture();f.Select(B,"switch to B clears old A immediately");f.Empty("post switch");f.Refresh("poll cached B frame");f.Empty("old cache excluded");Check(!f.Receiver.TryRender(cached,()=>{throw new Exception("stale callback executed");}),"old view cannot execute callback");
 }}
