  f.Select(A,"initial A");var ticket=f.Reserve(B);if(stage!="read issued before boundary")f.Receiver.MarkBytes(ticket);
  var parsed=FrameCodec.Parse(Json.Serialize(Raw(B,500,12,8)),(uint)B,1700000000000L+f.Now);
  f.Select(B,"switch with paused "+stage);long water=f.View.Boundary.Watermark;
  if(stage=="cross-boundary half frame"){var continuation=f.ReserveRead(ticket);f.Receiver.MarkBytes(continuation);Check(continuation.OriginSeq>=ticket.OriginSeq,"continuation reserves distinct read without rewriting earliest origin");}
  if(stage=="read issued before boundary")f.Receiver.MarkBytes(ticket);
  bool accepted=f.CommitAttempt(ticket,parsed,0,"release paused "+stage);f.Receiver.EndTransport(ticket,true);f.Refresh("release paused "+stage);Check(!accepted,"in-flight old origin rejected at "+stage);Check(ticket.OriginSeq<=water,"old read reservation is at or below switch watermark");f.Empty(stage);
 }}
