 static void W15(){using(var f=ReadyB()){
  long water=f.View.Boundary.Watermark,generation=f.View.Boundary.SelectionGeneration;var ids=new List<long>();var sessions=new List<long>();
  foreach(var item in new[]{new long[]{500,12,8},new long[]{522,13,8},new long[]{544,17,12}}){f.Send(B,item[0],item[1],item[2],"normal one-frame transport "+item[0]);ids.Add(f.View.Current.Stamp.TransportConnectionId);sessions.Add(f.View.Current.Stamp.SourceSessionGeneration);Check(f.View.Boundary.Watermark==water&&f.View.Boundary.SelectionGeneration==generation,"normal EOF/Open does not create observation boundary");}
  Check(ids.Distinct().Count()==3,"three independent normal transports used");Check(sessions.Distinct().Count()==1,"normal transport changes preserve source session");f.Values(44,5,4,80,"three-transport normal measurement");
  var older=f.Reserve(B);f.Receiver.MarkBytes(older);f.Send(B,566,18,13,"newer sequence commits first");Check(!f.Commit(older,555,18,13,"older origin late commit"),"older sequence key cannot overwrite current measurement");
  f.Now+=100;var batch=f.Reserve(B);f.Receiver.MarkBytes(batch);Check(f.Commit(batch,588,19,14,"batch ordinal zero",0,100000,"estimate",false),"ordinal zero accepted");Check(f.Commit(batch,610,20,15,"batch ordinal one",1,100000,"estimate",false),"same-origin later ordinal accepted");string id=f.View.Current.Stamp.FrameId;Check(!f.Commit(batch,610,20,15,"duplicate frame ID",1,100000,"estimate",false),"duplicate origin/ordinal frame rejected");Check(f.View.Current.Stamp.FrameId==id,"duplicate does not replace current frame");Check(!f.Commit(batch,588,19,14,"older ordinal after newer",0),"older same-origin ordinal cannot go backwards");
 }}
 static void E01(){using(var f=ReadyB()){
  FullB(f);for(int i=0;i<2500;i++){int pid=50000+i;f.Identity[pid]=pid;var ticket=f.Reserve(pid);f.Reject(ticket,"new invalid publisher");Check(f.Receiver.SourceCount<=MonitorReceiver.MaximumSources&&f.Receiver.TransportCount<=MonitorReceiver.MaximumTransports,"invalid publisher cleanup keeps source and transport bounded");if(i%500==0)f.Refresh("resource cleanup checkpoint "+i);}Check(f.History.SelectedPid==B&&f.History.HasBaseline,"invalid foreign publishers do not replace B");
  var pending=new List<ReceiverTicket>();bool full=false;for(int i=0;i<MonitorReceiver.MaximumSources+2;i++){int pid=60000+i;f.Identity[pid]=pid;try{pending.Add(f.Reserve(pid));}catch(InvalidOperationException){full=true;break;}}Check(full&&f.Receiver.SourceCount<=MonitorReceiver.MaximumSources,"source cap rejects excess active publishers explicitly");foreach(var ticket in pending)f.Receiver.EndTransport(ticket,false);f.Refresh("release all rejected-source slots");Check(f.View.Boundary.SelectedPid==B,"source cap does not rebind B");
  pending.Clear();for(int i=0;i<MonitorReceiver.MaximumTransports;i++)pending.Add(f.Reserve(B));full=false;try{f.Reserve(B);}catch(InvalidOperationException){full=true;}Check(full&&f.Receiver.TransportCount==MonitorReceiver.MaximumTransports,"transport active cap exact and explicit");foreach(var ticket in pending)f.Receiver.EndTransport(ticket,true);Check(f.Receiver.TransportCount==0,"normal completion releases all transport slots");
  var batch=f.Reserve(B);f.Receiver.MarkBytes(batch);for(int i=0;i<MonitorReceiver.MaximumFramesPerTransport;i++)Check(f.CommitAttempt(batch,FrameCodec.Parse(Json.Serialize(Raw(B,544,17,12)),(uint)B,1700000000000L+f.Now),i),"bounded ordinal heartbeat "+i);Check(!f.CommitAttempt(batch,FrameCodec.Parse(Json.Serialize(Raw(B,544,17,12)),(uint)B,1700000000000L+f.Now),MonitorReceiver.MaximumFramesPerTransport),"one transport cannot grow dedup state without bound");f.Refresh("bounded transport frame capacity");
 }}
 static Dictionary<string,object> Legacy(int pid,long utc){var raw=Raw(pid,500,12,8);raw["schema"]=1;foreach(string key in FrameCodec.measuredNumbers)raw.Remove(key);return FrameCodec.Parse(Json.Serialize(raw),(uint)pid,utc);}
 static void E02(){using(var f=ReadyB()){
  f.Now+=100;var ticket=f.Reserve(B);f.Receiver.MarkBytes(ticket);Check(f.CommitAttempt(ticket,Legacy(B,1700000000000L+f.Now),0),"legacy all-null measurement frame accepted safely");f.Receiver.EndTransport(ticket,true);f.Refresh("legacy missing measured counters");f.Empty("legacy no measured baseline");long generation=f.View.Boundary.SelectionGeneration;
  Check(!f.Send(B,500,12,8,"legacy to measured transition trigger"),"first changed measurement-capability frame triggers boundary and is discarded");Check(f.View.Boundary.SelectionGeneration>generation,"measurement-capability transition changes generation");f.Send(B,500,12,8,"second measured frame becomes baseline");f.Baseline(500,12,8,"schema transition does not poison rolling sample set");f.Send(B,522,13,8,"measured later1");f.Send(B,544,17,12,"measured later2");f.Values(44,5,4,80,"measurement resumes after legacy frame");
  f.Now+=100;ticket=f.Reserve(B);f.Receiver.MarkBytes(ticket);Check(!f.CommitAttempt(ticket,Legacy(B,1700000000000L+f.Now),0),"measured to legacy transition also discards triggering frame");f.Receiver.EndTransport(ticket,true);f.Refresh("measured to legacy boundary");f.Empty("reverse measurement capability transition");
 }}
 static void E03(){using(var f=ReadyB()){FullB(f);Check(!f.Send(B,545,17,12,"token grows without any successful input"),"positive token delta with zero input delta rejected");f.Empty("inconsistent zero-input token growth");}using(var f=ReadyB()){Check(!f.Send(B,1,0,0,"impossible initial tokens without inputs"),"positive total tokens with no inputs rejected at first frame");f.Empty("impossible initial token count");}}
 static void E04(){using(var f=ReadyB()){
  f.Send(B,500,12,8,"queued-render rolling baseline",100);long oldBaseline=f.History.BaselineMonotonicMilliseconds.Value;for(int i=1;i<=120;i++)f.Send(B,500+i,12+i,8+i,"continuous frame before queued render "+i,1000);var queued=f.Receiver.Capture();f.Now+=1500;ReceiverView painted;
  Check(MonitorApp.ApplyView(f.Window,f.History,f.Receiver,queued,p=>true,out painted),"still-live queued view can paint");Check(painted.NowMilliseconds==f.Now,"production final paint gate recaptures current monotonic time");Check(f.History.BaselineMonotonicMilliseconds>=f.Now-120000&&f.History.BaselineMonotonicMilliseconds>oldBaseline,"queued old time cannot extend rolling baseline");Check(f.History.ObservedMilliseconds<=120000,"queued display coverage stays bounded");f.Refresh("after 1500ms queued callback");
 }}
 static void E05(){using(var f=ReadyB()){
  f.Now+=100;var completed=f.Reserve(B);f.Receiver.MarkBytes(completed);Check(f.Commit(completed,500,12,8,"completed normal transport"),"normal frame accepted before close");long generation=f.View.Boundary.SelectionGeneration,water=f.View.Boundary.Watermark;f.Receiver.EndTransport(completed,false);f.Reject(completed,"late error after normal EOF");f.Refresh("late callbacks after normal transport completion");Check(f.View.Boundary.SelectionGeneration==generation&&f.View.Boundary.Watermark==water&&f.History.HasBaseline,"normal completion is idempotent against late failure callbacks");
  var stale=f.Reserve(B);f.Receiver.MarkBytes(stale);f.Select(A,"switch away from pending B");f.Select(B,"switch back then fresh B");f.Send(B,522,13,8,"fresh B after new barrier");generation=f.View.Boundary.SelectionGeneration;f.Receiver.EndTransport(stale,false);f.Reject(stale,"old transport failure after newer B accepted");f.Refresh("old failure cannot invalidate newer selected window");Check(f.View.Boundary.SelectionGeneration==generation&&f.History.BaselineTokens==522,"pre-watermark late transport error cannot clear new baseline");
 }}
 static void E06(){using(var f=new Fixture()){
  f.Select(A,"old A before concurrent switching");f.Send(A,100,10,5,"old A baseline");f.Send(A,120,15,9,"old A later1");f.Send(A,120,15,9,"old A later2");var oldA=f.Receiver.Capture();Exception workerError=null;bool stop=false;var entered=new ManualResetEvent(false);
  var noise=new Thread(()=>{try{for(int i=0;i<400&&!Volatile.Read(ref stop);i++){int pid=i%2==0?A:C;var ticket=f.Reserve(pid);f.Receiver.MarkBytes(ticket);f.CommitAttempt(ticket,FrameCodec.Parse(Json.Serialize(Raw(pid,1000+i,100+i,50+i)),(uint)pid,1700000000000L+f.Now),0);f.Receiver.EndTransport(ticket,true);entered.Set();Thread.Sleep(1);}}catch(Exception e){workerError=e;entered.Set();}});noise.IsBackground=true;noise.Start();Check(entered.WaitOne(1000),"concurrent foreign producer enters receiver");
  try{for(int i=0;i<100;i++){var selected=MonitorApp.ApplySelection(f.Window,f.History,f.Receiver,B,p=>true);f.AtomicRecord(selected,"atomic B selection under foreign activity "+i);Check(selected.Boundary.SelectedPid==B&&f.History.SelectedPid==B,"atomic selection paints selected PID immediately");f.Empty("atomic B clear "+i);Check(!MonitorApp.ApplyView(f.Window,f.History,f.Receiver,oldA,p=>true),"old A queued render remains rejected under concurrent commits");var current=MonitorApp.ApplyCurrent(f.Window,f.History,f.Receiver,p=>true);f.AtomicRecord(current,"atomic current refresh while no eligible B exists "+i);Check(current.Boundary.SelectedPid==B&&current.Current==null,"atomic current refresh cannot substitute A/C");f.Empty("atomic current B "+i);}}
  finally{Volatile.Write(ref stop,true);Check(noise.Join(2000),"foreign publisher thread exits");entered.Dispose();}Check(workerError==null,"concurrent producer did not throw");FullB(f);f.Values(44,5,4,80,"B recovers after atomic empty refreshes");
  stop=false;entered=new ManualResetEvent(false);workerError=null;var publisher=new Thread(()=>{try{for(int i=1;i<=100&&!Volatile.Read(ref stop);i++){var ticket=f.Reserve(B);f.Receiver.MarkBytes(ticket);f.CommitAttempt(ticket,FrameCodec.Parse(Json.Serialize(Raw(B,544+22*i,17+i,12+i)),(uint)B,1700000000000L+f.Now),0);f.Receiver.EndTransport(ticket,true);entered.Set();Thread.Sleep(1);}}catch(Exception e){workerError=e;entered.Set();}});publisher.IsBackground=true;publisher.Start();Check(entered.WaitOne(1000),"concurrent selected publisher enters receiver");
  try{for(int i=0;i<100;i++){var painted=MonitorApp.ApplyCurrent(f.Window,f.History,f.Receiver,p=>true);f.AtomicRecord(painted,"atomic selected refresh under high-frequency B "+i);Check(painted.Current!=null&&painted.Current.Stamp.ActualPid==B&&f.History.SelectedPid==B,"every atomic current paint is selected B");Check(f.History.CalculatedWindowTokens==Convert.ToInt64(painted.Current.Data["totalInputTokens"])-f.History.BaselineTokens,"painted measurement matches same locked current frame");Check(Text(f.Window,"ChartSource").Contains("PID "+B),"actual UI source label stays B during high-frequency commits");}}
  finally{Volatile.Write(ref stop,true);Check(publisher.Join(2000),"selected publisher thread exits");entered.Dispose();}Check(workerError==null,"selected concurrent publisher did not throw");
 }}
 [STAThread]public static int Main(string[] args){
  if(args.Length!=2){Console.Error.WriteLine("usage: tests.exe Monitor.xaml new-report.json");return 2;}xaml=Path.GetFullPath(args[0]);report=Path.GetFullPath(args[1]);if(File.Exists(report)){Console.Error.WriteLine("Refusing to overwrite existing evidence: "+report);return 2;}var inputHashes=HashInputs();
  Run("W01","old cached frame barrier",W01);Run("W02","paused reads / parse / commit / half-frame origins",W02);Run("W03","queued stale render callback",W03);Run("W04","three-source interleaving and pinned source",W04);Run("W05","switch first-frame raw baseline",W05);Run("W06","first later sample and duplicate polling",W06);Run("W07","independent frame and denominator gates",W07);Run("W08","invalid B plus 100 foreign updates and automatic recovery",W08);Run("W09","recovery baseline excludes disconnected traffic",W09);Run("W10","zero/small/missing/out-of-range denominator",W10);Run("W11","independent frame count and rolling sample gates",W11);Run("W12","revocation identity epoch counters backend exhaustion",W12);Run("W13","rolling boundary and delayed UI stale receipts",W13);Run("W14","B-only oracle and removal counterfactual",W14);Run("W15","normal one-frame transports ordinal ordering dedup",W15);
  Run("E01","bounded invalid publisher / source / transport / ordinal state",E01);Run("E02","legacy measurement capability transition",E02);Run("E03","zero-input token growth inconsistency",E03);Run("E04","final paint refreshes queued rolling time",E04);Run("E05","late transport errors are idempotent across barrier",E05);
  Run("E06","atomic switch clear and current paint during concurrent publishers",E06);
  bool inputsUnchanged=Json.Serialize(inputHashes)==Json.Serialize(HashInputs());var result=new{candidateUiVersion=MonitorApp.UiVersion,source="controlled offline publishers; production candidate Receiver/History/ApplyView/RenderCharts/XAML",syntheticOnly=true,inputHashes,inputsUnchanged,providerApiRequests=0,keyUsed=false,gpu="off",plannedTestCases=15,extraRegressionCases=6,testCases=Cases.Count,passedCases=Cases.Count-failures,failedCases=failures,assertions,cases=Cases,trace=Trace,utc=DateTimeOffset.UtcNow.ToString("o")};File.WriteAllText(report,Json.Serialize(result),new UTF8Encoding(false));Console.WriteLine(Json.Serialize(new{plannedTestCases=15,extraRegressionCases=6,testCases=Cases.Count,passedCases=Cases.Count-failures,failedCases=failures,assertions,inputsUnchanged,providerApiRequests=0,keyUsed=false,gpu="off",report}));return failures==0&&inputsUnchanged?0:1;
 }
